def parse_json(text: str) -> object:
    pos = 0
    n = len(text)

    def skip_ws():
        nonlocal pos
        while pos < n and text[pos] in ' \t\n\r':
            pos += 1

    def parse_string():
        nonlocal pos
        pos += 1
        chars = []
        while pos < n:
            c = text[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if ord(c) < 0x20:
                raise ValueError("control character in string")
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("incomplete escape")
                esc = text[pos]
                pos += 1
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    if pos + 4 > n:
                        raise ValueError("incomplete \\u escape")
                    hex_str = text[pos:pos + 4]
                    for ch in hex_str:
                        if ch not in '0123456789abcdefABCDEF':
                            raise ValueError("invalid hex digit in \\u escape")
                    pos += 4
                    cp = int(hex_str, 16)
                    if 0xD800 <= cp <= 0xDBFF:
                        if pos + 2 > n or text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError("unpaired high surrogate")
                        pos += 2
                        if pos + 4 > n:
                            raise ValueError("incomplete \\u escape")
                        hex2 = text[pos:pos + 4]
                        for ch in hex2:
                            if ch not in '0123456789abcdefABCDEF':
                                raise ValueError("invalid hex digit in \\u escape")
                        pos += 4
                        cp2 = int(hex2, 16)
                        if 0xDC00 <= cp2 <= 0xDFFF:
                            combined = 0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)
                            chars.append(chr(combined))
                        else:
                            raise ValueError("unpaired high surrogate")
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError("unpaired low surrogate")
                    else:
                        chars.append(chr(cp))
                else:
                    raise ValueError("invalid escape sequence")
            else:
                chars.append(c)
                pos += 1
        raise ValueError("unterminated string")

    def parse_number():
        nonlocal pos
        start = pos
        if text[pos] == '-':
            pos += 1
        if pos >= n:
            raise ValueError("invalid number")
        if text[pos] == '0':
            pos += 1
            if pos < n and text[pos].isdigit():
                raise ValueError("leading zero")
        elif text[pos].isdigit():
            while pos < n and text[pos].isdigit():
                pos += 1
        else:
            raise ValueError("invalid number")
        is_float = False
        if pos < n and text[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not text[pos].isdigit():
                raise ValueError("missing digits after decimal point")
            while pos < n and text[pos].isdigit():
                pos += 1
        if pos < n and text[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < n and text[pos] in '+-':
                pos += 1
            if pos >= n or not text[pos].isdigit():
                raise ValueError("missing digits after exponent")
            while pos < n and text[pos].isdigit():
                pos += 1
        s = text[start:pos]
        return float(s) if is_float else int(s)

    stack = []

    def place_or_done():
        if not stack:
            return 'done'
        top = stack[-1]
        if top[0] == 'arr':
            top[1].append(value)
            return 'array_after'
        else:
            top[1][top[4]] = value
            return 'obj_after'

    value = None
    expect = 'value'

    while True:
        if expect == 'done':
            skip_ws()
            if pos != n:
                raise ValueError("trailing content")
            return value

        if expect == 'value':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            c = text[pos]
            if c == '{':
                pos += 1
                skip_ws()
                if pos < n and text[pos] == '}':
                    pos += 1
                    value = {}
                    expect = place_or_done()
                else:
                    stack.append(('obj', {}, 0, set(), None))
                    expect = 'obj_key'
            elif c == '[':
                pos += 1
                skip_ws()
                if pos < n and text[pos] == ']':
                    pos += 1
                    value = []
                    expect = place_or_done()
                else:
                    stack.append(('arr', [], 0))
                    expect = 'value'
            elif c == '"':
                value = parse_string()
                expect = place_or_done()
            elif c == 't':
                if text[pos:pos + 4] == 'true':
                    pos += 4
                    value = True
                    expect = place_or_done()
                else:
                    raise ValueError("invalid literal")
            elif c == 'f':
                if text[pos:pos + 5] == 'false':
                    pos += 5
                    value = False
                    expect = place_or_done()
                else:
                    raise ValueError("invalid literal")
            elif c == 'n':
                if text[pos:pos + 4] == 'null':
                    pos += 4
                    value = None
                    expect = place_or_done()
                else:
                    raise ValueError("invalid literal")
            elif c == '-' or ('0' <= c <= '9'):
                value = parse_number()
                expect = place_or_done()
            else:
                raise ValueError("unexpected character")

        elif expect == 'obj_key':
            skip_ws()
            if pos >= n or text[pos] != '"':
                raise ValueError("expected string key")
            key = parse_string()
            top = stack[-1]
            if key in top[3]:
                raise ValueError("duplicate key")
            top[3].add(key)
            top[4] = key
            expect = 'obj_colon'

        elif expect == 'obj_colon':
            skip_ws()
            if pos >= n or text[pos] != ':':
                raise ValueError("expected colon")
            pos += 1
            expect = 'value'

        elif expect == 'array_after':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            if text[pos] == ',':
                pos += 1
                expect = 'value'
            elif text[pos] == ']':
                pos += 1
                top = stack.pop()
                value = top[1]
                expect = place_or_done()
            else:
                raise ValueError("expected comma or closing bracket")

        elif expect == 'obj_after':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            if text[pos] == ',':
                pos += 1
                expect = 'obj_key'
            elif text[pos] == '}':
                pos += 1
                top = stack.pop()
                value = top[1]
                expect = place_or_done()
            else:
                raise ValueError("expected comma or closing brace")

        else:
            raise AssertionError("internal error")
